-- Sample community content: Hyderabad running locations, a sample event
-- calendar for October to December 2026, and eight running plans.
--
-- Everything here is SAMPLE content and identifiable as such:
--   * every id starts with 5eed (locations 5eed0001, events 5eed0002,
--     programmes 5eed0003, programme sessions 5eed0004);
--   * created_by is null (rows created in the app always record their author);
--   * event titles start with "Sample:" and descriptions say the event is not
--     officially organised; locations are verified = false.
-- Location coordinates were checked against OpenStreetMap (object ids below);
-- access details are only claimed where OpenStreetMap records them.
--
-- Safe to run more than once and never changes existing rows: every insert
-- skips rows that already exist (by id, by unique slug/session, or for
-- locations by name). No users, RSVPs, enrolments, workouts or rewards.

-- ---------------------------------------------------------------------------
-- Running plans category
-- ---------------------------------------------------------------------------

alter table public.programmes drop constraint if exists programmes_category_check;
alter table public.programmes add constraint programmes_category_check
  check (category in ('couch_to_5k', 'general_fitness', 'training_and_shine', 'running'));

-- ---------------------------------------------------------------------------
-- Locations (skipped when a location with the same name already exists)
-- ---------------------------------------------------------------------------

insert into public.locations (id, name, kind, latitude, longitude, address, verified)
select v.id::uuid, v.name, v.kind::public.location_kind, v.latitude, v.longitude, v.address, false
from (values
  ('5eed0001-0000-4000-8000-000000000001', 'KBR National Park', 'park', 17.420177, 78.420523, 'Banjara Hills, Hyderabad'), -- OSM way/28268610
  ('5eed0001-0000-4000-8000-000000000002', 'People''s Plaza, Necklace Road', 'lake_loop', 17.418925, 78.465790, 'Necklace Road, Hussain Sagar, Hyderabad'), -- OSM way/79584064
  ('5eed0001-0000-4000-8000-000000000003', 'Sanjeevaiah Park', 'park', 17.432007, 78.475802, 'Begumpet, Hyderabad'), -- OSM way/29124107
  ('5eed0001-0000-4000-8000-000000000004', 'Durgam Cheruvu Secret Lake Park', 'lake_loop', 17.431145, 78.392050, 'Madhapur, Hyderabad'), -- OSM node/2713936303
  ('5eed0001-0000-4000-8000-000000000005', 'Botanical Gardens, Kondapur', 'park', 17.455051, 78.356984, 'Masjid Banda Road, Kondapur, Hyderabad'), -- OSM way/29124485
  ('5eed0001-0000-4000-8000-000000000006', 'GMC Balayogi Athletic Stadium', 'track', 17.446216, 78.344132, 'Gachibowli, Hyderabad'), -- OSM way/665330878
  ('5eed0001-0000-4000-8000-000000000007', 'Indira Park', 'park', 17.414712, 78.483112, 'Kavadiguda, Hyderabad'), -- OSM way/29124111
  ('5eed0001-0000-4000-8000-000000000008', 'Jalagam Vengal Rao Park', 'park', 17.422917, 78.448178, 'Banjara Hills, Hyderabad'), -- OSM way/29124311
  ('5eed0001-0000-4000-8000-000000000009', 'Gandipet Lake Park (Osman Sagar)', 'lake_loop', 17.381930, 78.315804, 'Gandipet, Ranga Reddy district'), -- OSM way/626348183
  ('5eed0001-0000-4000-8000-000000000010', 'Fakhruddin Gutta (Khajaguda hills)', 'trail', 17.409789, 78.365184, 'Khajaguda, Hyderabad'), -- OSM node/7380335856
  ('5eed0001-0000-4000-8000-000000000011', 'Chacha Nehru Park', 'park', 17.400893, 78.450141, 'Masab Tank, Hyderabad'), -- OSM way/29124405
  ('5eed0001-0000-4000-8000-000000000012', 'Safilguda Lake Park', 'lake_loop', 17.463388, 78.536277, 'Neredmet, Malkajgiri, Hyderabad') -- OSM relation/10669535
) as v (id, name, kind, latitude, longitude, address)
where not exists (select 1 from public.locations l where lower(l.name) = lower(v.name))
on conflict do nothing;

-- ---------------------------------------------------------------------------
-- Events (all times IST). The location is looked up by name, so an existing
-- location with the same name is used instead of a duplicate.
-- ---------------------------------------------------------------------------

insert into public.events (id, title, description, starts_at, ends_at, location_id, capacity, status)
select v.id::uuid, v.title, v.description, v.starts_at::timestamptz, v.ends_at::timestamptz,
  (select l.id from public.locations l where lower(l.name) = lower(v.location) order by (l.id = v.location_id::uuid) desc limit 1),
  v.capacity, 'published'
from (values
  ('5eed0002-0000-4000-8000-000000000001', 'Sample: Saturday community 5K',
