-- ---------------------------------------------------------------------------
-- Running plans (open enrolment)
-- ---------------------------------------------------------------------------

insert into public.programmes (id, slug, title, summary, kind, category, level, duration_weeks, sessions_per_week, enrolment, published, sort_order) values
  ('5eed0003-0000-4000-8000-000000000001', 'walk-to-run-foundation', 'Walk to run foundation', 'Four gentle weeks of brisk walking with short, easy jogs, for anyone not yet ready for Couch to 5K.', 'custom', 'running', 'beginner', 4, 3, 'open', true, 210),
  ('5eed0003-0000-4000-8000-000000000002', 'consistency-habit-builder', 'Consistency habit builder', 'Four weeks of short 15–20 minute sessions that make moving three times a week a habit.', 'custom', 'running', 'beginner', 4, 3, 'open', true, 220),
  ('5eed0003-0000-4000-8000-000000000003', 'return-to-running', 'Return to running', 'Six weeks of gradual walk-run sessions for runners coming back after a break of a few months.', 'custom', 'running', 'beginner', 6, 3, 'open', true, 230),
  ('5eed0003-0000-4000-8000-000000000004', '5k-improvement', '5K improvement', 'Six weeks of intervals, easy runs and long runs for runners who can already run 5 km and want to get faster.', 'custom', 'running', 'intermediate', 6, 3, 'open', true, 240),
  ('5eed0003-0000-4000-8000-000000000005', '10k-preparation', '10K preparation', 'Eight weeks of tempo, easy and long runs that take you from running 5K comfortably to finishing a 10K.', 'custom', 'running', 'intermediate', 8, 3, 'open', true, 250),
  ('5eed0003-0000-4000-8000-000000000006', 'endurance-base', 'Endurance base', 'Eight weeks of mostly easy running that builds your long run from 45 to 90 minutes.', 'custom', 'running', 'intermediate', 8, 3, 'open', true, 260),
  ('5eed0003-0000-4000-8000-000000000007', 'half-marathon-foundation', 'Half-marathon foundation', 'Twelve weeks of easy, quality, strength and long runs for runners who can run 10 km and want to cover 21.1 km.', 'custom', 'running', 'intermediate', 12, 4, 'open', true, 270),
  ('5eed0003-0000-4000-8000-000000000008', 'half-marathon-advanced', 'Half-marathon advanced', 'Ten demanding weeks of intervals, threshold runs and goal-pace long runs for experienced half-marathon runners.', 'custom', 'running', 'advanced', 10, 4, 'open', true, 280)
on conflict do nothing;

